tate(prior?.educationNotes||""),[fundalHeight,setFundalHeight]=useState(prior?.fundalHeight||""),[fetalSurveillance,setFetalSurveillance]=useState(prior?.fetalSurveillance||""),[deliveryPlanning,setDeliveryPlanning]=useState(prior?.deliveryPlanning||"");
 const reviewReadings=filterReviewReadings(allReadings,period,start,end),stats=analyze(reviewReadings,data.settings),pattern=glucosePattern(stats),periodLabel=period==="custom"?`${fmt(start)} to ${fmt(end)}`:`previous ${period} days`;
